using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace PowerShapeBridge {
 internal static class OwnedGeometryExportVerificationTests {
  static void Require(bool ok,string error){if(!ok)throw new InvalidOperationException(error);}
  static Dictionary<string,object> Clone(Dictionary<string,object> value){return Program.Json.Deserialize<Dictionary<string,object>>(Program.Json.Serialize(value));}
  static Dictionary<string,string> Hashes(string root){return Directory.GetFiles(root,"*",SearchOption.AllDirectories).ToDictionary(p=>p,p=>Program.Hash(p));}
  // Deliberately no mutation methods or callbacks on the independent read context.
  internal sealed class Context : OwnedGeometryExportVerification.IContext {
   internal Dictionary<string,object> Snapshot,Listing,Settings;internal string Fault;internal int Reads;
   internal Context(OwnedGeometryExportTests.Context previous){Snapshot=Clone(previous.Observation());Listing=Clone(previous.Listing);Settings=Clone(previous.Settings);}
   public Dictionary<string,object> Observation(){Reads++;var result=Clone(Snapshot);if(Fault=="late_context"&&Reads>=4)result["processId"]=99;return result;}
   public Dictionary<string,object> Windows(){return Clone(Listing);}
   public Dictionary<string,object> ExportSettings(){var result=Clone(Settings);if(Fault=="settings")result["solidShading"]=false;return result;}
   public int Composite(int type,int nativeId){return Fault=="mapping"?999:type*100000+nativeId;}
   public void ConfirmDocument(){if(Fault=="retained_document")throw new InvalidOperationException("Retained independent document changed.");}
   public void Dispose(){}
  }
  internal static int Run() {
   Require(File.Exists(Path.Combine(Program.Root,".geometry-export-verification-fixture")),"Explicit isolated export verifier marker required; no CAD.");var rows=new List<Dictionary<string,object>>();
   foreach(string fault in new[]{"control","mixed_targets","receipt_sha","target_sha","summary_sha","step_sha","fence_sha","claim","output_bytes","missing_output","replaced_output","old_inspection","equal_inspection","expired_reads","settings","mapping","late_context","retained_document","wrong_window","foreign_model","unknown_export"}) {
    var f=new OwnedOperationPlanTests.Fixture(true,true);f.Snapshot["levelsContainingEntities"]=new[]{new Dictionary<string,object>{{"number",0},{"name","Synthetic"},{"activeRaw",1}}};var keys=fault=="mixed_targets"?new[]{new[]{40,5},new[]{21,8}}:new[]{new[]{40,5}};var parameters=OwnedGeometryExportTargetTests.Rebind(f,f.Snapshot,null,keys);string targetId=Guid.NewGuid().ToString("N"),executionId=Guid.NewGuid().ToString("N");var target=OwnedGeometryExportTargets.Prepare(f.Root,targetId,parameters);Require(Equals(target["state"],"owned_geometry_export_target_prepared_files"),"Target setup failed.");
    var executionContext=new OwnedGeometryExportTests.Context(f){Fault=fault=="unknown_export"?"export_throw":null,TargetPath=OwnedGeometryExportTargets.TargetPath(f.Root,targetId)};var executed=OwnedGeometryExport.Execute(f.Root,executionId,new Dictionary<string,object>{{"targetId",targetId},{"targetSha256",target["targetSha256"]}},executionContext);Require(Equals(executed["state"],fault=="unknown_export"?"owned_geometry_export_outcome_unknown":"owned_geometry_export_executed_unverified"),"Execution setup failed: "+Program.Json.Serialize(executed));string receiptSha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",executionId+".json"),executed);
    DateTime returned=fault=="unknown_export"?EntitySets.Expiry(executed["timestampUtc"]):NativeJournal.ForVerification(f.Root,executionId,(string)executed["planSha256"]).CommandReturnedUtc;OwnedRotationVerificationTests.WaitAfter(returned);var context=new Context(executionContext){Fault=fault};var inspection=Clone(context.Snapshot);inspection["timestampUtc"]=fault=="old_inspection"?f.Snapshot["timestampUtc"]:fault=="equal_inspection"?returned.ToString("o"):DateTime.UtcNow.ToString("o");string inspectionId=Guid.NewGuid().ToString("N");inspection["bridgeRequestId"]=inspectionId;if(fault=="foreign_model")((Dictionary<string,object>)inspection["model"])["id"]=99;string inspectionSha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",inspectionId+".json"),inspection);
    var listing=Clone(context.Listing);listing["timestampUtc"]=DateTime.UtcNow.ToString("o");listing["state"]="documents_listed_verified";string listingId=Guid.NewGuid().ToString("N"),listingSha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",listingId+".json"),listing);var args=new Dictionary<string,object>{{"executionRequestId",executionId},{"executionReceiptSha256",receiptSha},{"inspectionRequestId",inspectionId},{"inspectionSha256",inspectionSha},{"listingRequestId",listingId},{"listingSha256",listingSha},{"windowNumber",fault=="wrong_window"?99:1},{"modelId",9},{"expiresUtc",DateTime.UtcNow.AddSeconds(fault=="expired_reads"?-1:150).ToString("o")}};
    string folder=OwnedGeometryExportTargets.Folder(f.Root,targetId),output=OwnedGeometryExportTargets.TargetPath(f.Root,targetId);if(fault=="receipt_sha")args["executionReceiptSha256"]=new string('f',64);if(fault=="target_sha")File.AppendAllText(Path.Combine(folder,"target.json")," ");if(fault=="summary_sha")File.AppendAllText(Path.Combine(folder,"export-summary.json")," ");if(fault=="step_sha")File.AppendAllText(Path.Combine(folder,"000000.returned.json")," ");if(fault=="fence_sha")File.AppendAllText(OwnedGeometryExportTargets.ExportFencePath(f.Root,(string)executed["copyId"])," ");
    if(fault=="claim") {var claim=Program.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(folder,"export-once.json")));claim["operationId"]=Guid.NewGuid().ToString("N");File.WriteAllText(Path.Combine(folder,"export-once.json"),Program.Json.Serialize(claim));}if(fault=="output_bytes")File.AppendAllText(output,"changed");if(fault=="missing_output")File.Move(output,Path.Combine(f.Root,"retained-export.dmt"));if(fault=="replaced_output"){File.Move(output,Path.Combine(f.Root,"retained-export.dmt"));File.Copy(Path.Combine(f.Root,"retained-export.dmt"),output);}
    var before=Hashes(f.Root);string verificationId=Guid.NewGuid().ToString("N");var result=OwnedGeometryExportVerification.Verify(f.Root,verificationId,args,context);bool control=fault=="control"||fault=="mixed_targets";Require(Equals(result["state"],control?"observed_export_file_context_match_unqualified":"owned_geometry_export_verification_rejected"),fault+": "+Program.Json.Serialize(result));Require(before.All(p=>Program.Hash(p.Key)==p.Value),"Verification changed original file/journal/fence.");foreach(string flag in new[]{"exportAttempted","contextChangeAttempted","geometryMutationAttempted","cadSaveAttempted","geometryVerified","nativeProviderQualified","copyFenceReleased","retryAllowed"})Require(Equals(result[flag],false),"Verification acquired mutation authority.");Require(executionContext.Adds==keys.Length&&executionContext.Exports==1&&executionContext.Clears==(fault=="unknown_export"?0:1),"Independent verification repeated callbacks.");
    if(control) {using(var historical=new OwnedGeometryExportTargets.TargetLease(f.Root,targetId,(string)target["targetSha256"],true)){bool rejected=false;try{historical.Recheck();}catch(InvalidDataException){rejected=true;}Require(rejected,"Historical verification lease authorized execution.");}}
    rows.Add(new Dictionary<string,object>{{"fault",fault},{"root",f.Root},{"executionId",executionId},{"targetId",targetId},{"verificationId",verificationId},{"parameters",args},{"result",result},{"verificationReads",context.Reads},{"protectedHashes",before},{"artifactHashes",Hashes(f.Root)},{"cadConnectionAttempted",false}});
   }
   Directory.CreateDirectory(Path.Combine(Program.Root,"reports"));NativeJournal.Freeze(Path.Combine(Program.Root,"reports","geometry-export-verification-tests.json"),new Dictionary<string,object>{{"state","passed"},{"rows",rows},{"cadConnectionAttempted",false}});Console.WriteLine("PASS: "+rows.Count+" independent export verification cases; no CAD/fence release.");return rows.Count;
  }
 }
}
